package com.bct.ngtpa.apiservice.adapter.out.session.login;
import com.bct.ngtpa.apiservice.application.usecase.auth.login.otp.*;import com.bct.ngtpa.apiservice.application.dto.session.authflow.*;import com.bct.ngtpa.apiservice.application.port.out.LoginOtpSessionBindingPort;import com.bct.ngtpa.apiservice.application.usecase.session.authflow.*;import java.util.Objects;import reactor.core.publisher.Mono;
public final class LoginOtpSessionBindingAdapter implements LoginOtpSessionBindingPort {private final AuthFlowSessionLifecycleService lifecycle;public LoginOtpSessionBindingAdapter(AuthFlowSessionLifecycleService l){lifecycle=Objects.requireNonNull(l);}public Mono<Void> bind(LoginOtpSessionBindingCommand c){var id=new AuthFlowSessionId(c.authFlowSessionId());return lifecycle.load(new LoadAuthFlowSessionCommand(id,c.correlationId())).flatMap(o->{var s=o.orElseThrow(()->new IllegalStateException("Login OTP session unavailable"));if(s.scenario()!=AuthFlowScenario.LOGIN||s.status()!=c.expectedStatus()||!Objects.equals(s.activeOtpChallengeId(),c.expectedCurrentOtpChallengeId()))return Mono.error(new IllegalStateException("Login OTP binding state mismatch"));return lifecycle.updateActiveOtpChallenge(new UpdateAuthFlowOtpCommand(id,c.newOtpChallengeId(),c.correlationId())).then(Mono.defer(()->c.resultingStatus()==c.expectedStatus()?Mono.empty():lifecycle.updateStatus(new UpdateAuthFlowStatusCommand(id,c.resultingStatus(),c.correlationId())).then()));}).then();}}
